const view=document.createElement('main');view.className='square-workspace';view.innerHTML=`<section class="square-controls"><div class="eyebrow">ТИТАН АВТО · ЛЕНТА 3 × 3</div><h2>Одна серия. Девять кадров.</h2><p class="square-help">Модель, год, пробег, цена, телефон и палитра берутся из вкладки «Сторис». Фото загружаются отдельно. Выберите квадрат для редактирования; двигайте фото прямо в нём.</p><label class="upload-box"><input id="squarePhotos" type="file" accept="image/*" multiple hidden><strong>＋ Загрузить 9 фото</strong><small id="squareStatus">0 / 9 · можно добавлять частями</small></label><div class="square-actions"><button class="button secondary" id="squareReuse">Взять фото из сторис</button><button class="button secondary" id="squareClear">Новая серия</button></div><label class="field"><span>Серия / автомобиль</span><input id="squareSeries" value="1" type="number" min="1" max="9999"></label><label class="field"><span>Подпись выбранного квадрата <b id="squareSelected">1</b></span><textarea id="squareText" rows="4" maxlength="160"></textarea></label><p class="square-help">Подстановки: {model}, {year}, {mileage}, {price}, {phone}, {location}, {features}. Можно заменить их своим текстом или оставить поле пустым.</p><label class="field"><span>Размер текста</span><input id="squareFont" type="range" min="24" max="64" value="38"></label><label class="field"><span>Масштаб фото</span><input id="squareZoom" type="range" min="1" max="3" step="0.01" value="1"></label><label class="field"><span>Затемнение под текстом</span><input id="squareShade" type="range" min="0" max="0.9" step="0.05" value="0.65"></label><label class="field"><span>Порядок загрузки на стену</span><select id="squareOrder"><option value="reverse">Сначала нижний правый · новая публикация слева сверху</option><option value="direct">Сначала верхний левый · прямой порядок</option></select></label><div class="square-actions"><button class="button primary" id="squareZip">Скачать 9 PNG в ZIP</button><button class="button secondary" id="squareSingle">Скачать выбранный PNG</button><button class="button secondary" id="squareSave">Сохранить проект</button><label class="button secondary">Открыть проект<input id="squareOpen" type="file" accept=".json" hidden></label></div><p class="square-help" id="squareMessage">PNG 1080 × 1080. ZIP содержит 9 отдельных файлов с порядком публикации. Повторяющаяся рамка соединяет эту серию со следующей.</p></section><section class="square-preview"><div class="preview-head">Вид стены · 3 × 3 <span>1080 × 1080 каждый</span></div><div class="square-wall" id="squareWall"></div><div class="square-next"></div><p class="square-help">Числа поверх превью показывают порядок публикации и не попадают в PNG. Для другой позиции кадра используйте «Переместить» ниже.</p><div class="square-actions"><label>Переместить выбранное фото в ячейку <select id="squareMove">${Array.from({length:9},(_,i)=>`<option value="${i}">${i+1}</option>`).join('')}</select></label><button class="button secondary" id="squareSwap">Переместить</button><button class="button secondary" id="squareResetCrop">Сбросить кадрирование</button></div></section>`;document.body.append(view);
