el('storyFormat').onclick=()=>format(false);el('squareFormat').onclick=()=>format(true);
async function add(files){if(busy)return;busy=true;el('squarePhotos').disabled=true;try{const free=tiles.map((t,i)=>t.image?-1:i).filter(i=>i>=0);if(files.length>free.length)toast(`Можно добавить ещё ${free.length} фото`);for(let n=0;n<Math.min(files.length,free.length);n++){el('squareStatus').textContent=`Обрабатываю фото ${n+1}…`;const image=await loadImage(URL.createObjectURL(files[n]));try{const c=document.createElement('canvas'),scale=Math.min(1,2200/Math.max(image.width,image.height));c.width=Math.round(image.width*scale);c.height=Math.round(image.height*scale);c.getContext('2d').drawImage(image,0,0,c.width,c.height);const src=c.toDataURL('image/jpeg',.92);Object.assign(tiles[free[n]],{src,image:await loadImage(src)})}finally{URL.revokeObjectURL(image.src)}}}catch(e){toast('Не удалось прочитать фото: '+e.message)}finally{busy=false;el('squarePhotos').disabled=false;el('squarePhotos').value='';drawAll()}}
el('squarePhotos').onchange=e=>add([...e.target.files]);el('squareReuse').onclick=()=>{state.photos.slice(0,9).forEach((p,i)=>Object.assign(tiles[i],{image:p.image||p.img,src:(p.image||p.img)?.src||'',zoom:1,x:0,y:0}));drawAll()};
el('squareText').oninput=e=>{tiles[selected].text=e.target.value;render(selected)};el('squareZoom').oninput=e=>{tiles[selected].zoom=+e.target.value;render(selected)};['squareFont','squareShade','squareOrder'].forEach(id=>el(id).oninput=drawAll);document.querySelector('.controls').addEventListener('input',drawAll);document.querySelector('.controls').addEventListener('change',drawAll);el('parseBtn').addEventListener('click',drawAll);
el('squareSwap').onclick=()=>{const to=+el('squareMove').value;[tiles[selected],tiles[to]]=[tiles[to],tiles[selected]];select(to)};el('squareResetCrop').onclick=()=>{Object.assign(tiles[selected],{zoom:1,x:0,y:0});select(selected)};
canvases.forEach((c,i)=>{c.onpointerdown=e=>{select(i);drag={i,x:e.clientX,y:e.clientY,ox:tiles[i].x,oy:tiles[i].y};c.setPointerCapture(e.pointerId)};c.onpointermove=e=>{if(!drag||drag.i!==i)return;const t=tiles[i];if(!t.image)return;const scale=Math.max(1080/t.image.width,1080/t.image.height)*t.zoom,ratio=1080/c.getBoundingClientRect().width;t.x=Math.max(-1,Math.min(1,drag.ox+(e.clientX-drag.x)*ratio/Math.max(1,(t.image.width*scale-1080)/2)));t.y=Math.max(-1,Math.min(1,drag.oy+(e.clientY-drag.y)*ratio/Math.max(1,(t.image.height*scale-1080)/2)));render(i)};c.onpointerup=c.onpointercancel=()=>drag=null;c.addEventListener('wheel',e=>{e.preventDefault();tiles[i].zoom=Math.max(1,Math.min(3,tiles[i].zoom+(e.deltaY<0?.05:-.05)));select(i)},{passive:false})});
const blob=c=>new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(new Error('Ошибка PNG')),'image/png'));
