el('squareZip').onclick=async()=>{if(busy)return;if(tiles.some(t=>!t.image)){toast('Загрузите все 15 фото для полной серии');return}busy=true;el('squareZip').disabled=true;try{await document.fonts.ready;drawAll();const entries=[];for(let i=0;i<9;i++)entries.push(await TitanHoliday.entry(name(i),await blob(canvases[i])));entries.sort((a,b)=>a.name.localeCompare(b.name));triggerDownload(zipFiles(entries),`Титан Авто — ${safeName(el('model').value||'авто')} — серия ${el('squareSeries').value}.zip`);toast('Готово: 9 отдельных PNG в ZIP')}catch(e){toast('Ошибка экспорта: '+e.message)}finally{busy=false;el('squareZip').disabled=false}};
el('squareClear').onclick=()=>{if(confirm('Начать новую серию? Сохраните текущий проект перед очисткой.')){tiles=tiles.map((_,i)=>({image:null,src:'',text:defaults[i],zoom:1,x:0,y:0}));el('squareSeries').value=+el('squareSeries').value+1;select(0)}};
el('squareSave').onclick=()=>{const data={type:'titan-square-v1',tiles:tiles.map(({image,...t})=>t),settings:Object.fromEntries(['squareSeries','squareFont','squareShade','squareOrder'].map(id=>[id,el(id).value])),vehicle:Object.fromEntries([...fields,...settingFields].map(id=>[id,el(id).value]))};triggerDownload(new Blob([JSON.stringify(data)],{type:'application/json'}),`titan-squares-${el('squareSeries').value}.json`)};
