select=function(i){selected=i;el('squareSelected').textContent=i+1;el('squareText').value=tiles[i].text;el('squareZoom').value=tiles[i].zoom;el('squareHeading').value=tiles[i].heading??(i===0?'{model}':'');el('squareLinked').checked=tiles[i].heading==null&&i===0;drawAll()};
document.querySelector('.square-controls > .square-help').textContent='Загрузите фото здесь или в сторис — порядок общий. Нажмите кадр, чтобы изменить его текст. Двигайте фото внутри кадра; тяните значок ↔, чтобы переставить кадры.';
