el('squareHeading').oninput=e=>{tiles[selected].heading=e.target.value;el('squareLinked').checked=false;render(selected)};el('squareLinked').onchange=e=>{tiles[selected].heading=e.target.checked?null:resolved('{model}');select(selected)};
