canvases.forEach((c,i)=>{const handle=document.createElement('span');handle.className='square-reorder';handle.textContent='↔';handle.title='Перетащить фото';c.parentNode.append(handle);let moving=false,target=i;handle.onpointerdown=e=>{e.stopPropagation();e.preventDefault();moving=true;target=i;handle.setPointerCapture(e.pointerId);handle.classList.add('moving')};handle.onpointermove=e=>{if(!moving)return;const rects=canvases.map(c=>c.getBoundingClientRect());target=rects.findIndex(r=>e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom);canvases.forEach((c,j)=>c.parentNode.classList.toggle('drop-target',j===target))};handle.onpointerup=e=>{e.stopPropagation();if(moving&&target>=0&&target!==i&&state.photos[i]&&state.photos[target]){const p=state.photos.splice(i,1)[0];state.photos.splice(target,0,p);state.slot=target;save();renderThumbs();draw();select(target)}moving=false;handle.classList.remove('moving');canvases.forEach(c=>c.parentNode.classList.remove('drop-target'))};handle.onpointercancel=()=>{moving=false;canvases.forEach(c=>c.parentNode.classList.remove('drop-target'))};handle.onclick=e=>e.stopPropagation();
 const points=new Map();let pinch=null;const down=c.onpointerdown,move=c.onpointermove;c.onpointerdown=e=>{points.set(e.pointerId,{x:e.clientX,y:e.clientY});down(e);if(points.size===2){const p=[...points.values()];pinch={distance:Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y),zoom:tiles[i].zoom};drag=null}};c.onpointermove=e=>{if(points.has(e.pointerId))points.set(e.pointerId,{x:e.clientX,y:e.clientY});if(points.size===2&&pinch){const p=[...points.values()];tiles[i].zoom=Math.max(1,Math.min(3,pinch.zoom*Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y)/Math.max(1,pinch.distance)));el('squareZoom').value=tiles[i].zoom;render(i)}else move(e)};c.onpointerup=c.onpointercancel=e=>{points.delete(e.pointerId);pinch=null;drag=null};
});
