el('squareOpen').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;const data=await TitanSafety.readJSON(file);if(data.type!=='titan-square-v1'||data.tiles?.length!==9)throw Error('Это не проект квадратов');const photos=[];for(const [i,t] of data.tiles.entries()){if(!t.src)break;const res=await fetch(t.src);const p=await optimizedPhoto(new File([await res.blob()],`photo-${i+1}.jpg`,{type:'image/jpeg'}));if(t.storyCrop){Object.assign(p.single,t.storyCrop.single);Object.assign(p.collage,t.storyCrop.collage)}photos.push(p);cropCache.set(p,{customCrop:true,zoom:Math.max(1,Math.min(3,+t.zoom||1)),x:Math.max(-1,Math.min(1,+t.x||0)),y:Math.max(-1,Math.min(1,+t.y||0))})}state.photos.forEach(p=>URL.revokeObjectURL(p.url));state.photos=photos;tiles=data.tiles.map(t=>({...t,image:null,photo:null,heading:t.heading==null?null:String(t.heading).slice(0,100),text:String(t.text||'').slice(0,160)}));applyEditorData({...collectEditorData(),...data.vehicle});Object.entries(data.settings||{}).forEach(([id,v])=>{if(['squareSeries','squareFont','squareShade','squareOrder'].includes(id))el(id).value=v});save();renderThumbs();draw();select(0);toast('Проект открыт в обоих форматах')}catch(err){toast(err.message)}finally{e.target.value=''}};
